\set ON_ERROR_STOP on
INSERT INTO plugin_demo.notes VALUES ('z', repeat('x', 8388609));
DO $test$ BEGIN BEGIN WITH "__weft_source" AS MATERIALIZED (SELECT ROW_NUMBER() OVER (ORDER BY "r"."id" COLLATE pg_catalog."C" ASC) AS "__weft_ordinal", "r"."id" COLLATE pg_catalog."C" AS "__weft_page_key", "r"."owner" COLLATE pg_catalog."C" AS "__weft_field_1" FROM "plugin_demo"."notes" AS "r" WHERE (TRUE) AND (NULL::pg_catalog.text IS NULL OR "r"."id" COLLATE pg_catalog."C" > NULL::pg_catalog.text COLLATE pg_catalog."C") ORDER BY "r"."id" COLLATE pg_catalog."C" ASC LIMIT (10::pg_catalog.int8 + 1)), "__weft_guard" AS MATERIALIZED (SELECT CASE WHEN COALESCE(pg_catalog.sum(pg_catalog.octet_length(pg_catalog.convert_to(pg_catalog.row_to_json(f)::pg_catalog.text, 'UTF8'))),0) <= 8388608 THEN 1::pg_catalog.int8 ELSE 1::pg_catalog.int8 / (pg_catalog.count(*) - pg_catalog.count(*)) END AS ok FROM "__weft_source" AS f) SELECT f.* FROM "__weft_source" AS f ORDER BY f."__weft_ordinal" LIMIT ALL OFFSET (SELECT 1 - ok FROM "__weft_guard"); RAISE EXCEPTION 'byte guard failed to stop oversized result'; EXCEPTION WHEN division_by_zero THEN RAISE NOTICE 'byte guard raised SQLSTATE 22012'; END; END $test$;
